UPDATE tools SET short_description_en = 'Qualified European electronic signature.', long_description_en = 'Skribble is a Swiss electronic signature solution offering all three eIDAS levels: simple, advanced, and qualified. It stands out for its ease of use and Swiss/European compliance. For businesses operating between Switzerland and the EU, it''s a natural choice.' WHERE slug = 'skribble';
UPDATE tools SET short_description_en = 'Networked notes with built-in AI and backlinks.', long_description_en = 'Reflect combines networked note-taking with AI to create a personal thinking assistant. It transcribes voice notes, generates summaries, and suggests connections between ideas. It''s a more accessible Roam Research with an AI layer that adds daily value.' WHERE slug = 'reflect-notes';
UPDATE tools SET short_description_en = 'Online company creation and legal management.', long_description_en = 'Legalstart simplifies legal procedures for entrepreneurs: company formation, contract drafting, bylaw amendments, trademark registration. It guides you step by step with smart forms and auto-generated documents. It''s the pragmatic choice for freelancers who want to handle routine legal matters without a lawyer.' WHERE slug = 'legalstart';
UPDATE tools SET short_description_en = 'Visual whiteboard for knowledge management.', long_description_en = 'Heptabase organises knowledge visually on infinite whiteboards. Unlike Miro (collaboration-focused), Heptabase is built for individual thinking: organising ideas, structuring a course, planning complex projects. It''s the crossover between a mind-mapping tool and a PKM.' WHERE slug = 'heptabase';
UPDATE tools SET short_description_en = 'Complete payroll solution for SMEs.', long_description_en = 'Sage Paie is a comprehensive payroll management solution for French SMEs. It covers the full payroll cycle: pay slip generation, social declarations, absence management, and payroll cost tracking. Its integration with the Sage ecosystem (accounting, commercial management) makes it a coherent choice for businesses already using Sage.' WHERE slug = 'sage-paie';
UPDATE tools SET short_description_en = 'Podcast recording, editing, and transcription.', long_description_en = 'Podcastle is an all-in-one podcast studio: recording, editing, transcription, and publishing. It uses AI to improve audio quality, auto-transcribe, and even generate synthetic voices. For audio content creators who want a streamlined workflow, it''s a more accessible alternative to Descript.' WHERE slug = 'podcastle';
UPDATE tools SET short_description_en = 'All-in-one platform for expenses, cards, and invoices.', long_description_en = 'Payhawk combines corporate cards, expense reports, and supplier invoice management in a single platform. It''s the most complete solution in this category, designed for growing companies that want one tool instead of three. Native ERP integration and multi-level approval workflows make it a solid choice for demanding CFOs.' WHERE slug = 'payhawk';
UPDATE tools SET short_description_en = 'LinkedIn analytics for content creators.', long_description_en = 'Shield App provides detailed LinkedIn analytics: follower growth, post performance, best publishing times, and benchmarks. For LinkedIn content creators who want to optimise their strategy, it''s the missing dashboard that LinkedIn doesn''t provide.' WHERE slug = 'shield-app';
UPDATE tools SET short_description_en = 'Open-source PKM with knowledge graph.', long_description_en = 'Logseq is the open-source alternative to Roam Research. It offers the same networked note-taking features (bidirectional links, knowledge graph, outliner) but with local Markdown storage. For those who want Roam''s power without the price and with full data control, it''s the obvious choice.' WHERE slug = 'logseq';
UPDATE tools SET short_description_en = '1-click automations between 1000+ apps.', long_description_en = 'Integrately offers pre-configured 1-click automations. Where Zapier requires building each workflow from scratch, Integrately provides millions of ready-to-use automations. It''s the tool for non-technical users who want to automate without configuring.' WHERE slug = 'integrately';
UPDATE tools SET short_description_en = 'Centralised secret and environment variable management.', long_description_en = 'Doppler centralises environment variable and secret management for development teams. Instead of scattered .env files, Doppler provides a single dashboard with versioning, permissions, and automatic deployment to all environments. It''s the modern standard for team-level secret management.' WHERE slug = 'doppler';
UPDATE tools SET short_description_en = 'Business expense management and corporate cards.', long_description_en = 'Moss centralises business expense management with physical and virtual cards, approval workflows, and direct accounting integration. For freelancers and small teams, it''s a way to automate expense tracking without Excel spreadsheets. It stands out for the speed of virtual card issuance and granular per-project, per-person budget control.' WHERE slug = 'moss';
UPDATE tools SET short_description_en = 'Collaborative doc that works like an app.', long_description_en = 'Coda merges document, spreadsheet, and application into a single tool. Unlike Notion which remains documentation-centric, Coda lets you build real business applications without code: custom CRM, project tracking, internal automations. It''s the tool for those who find spreadsheets lack logic and dedicated tools lack flexibility.' WHERE slug = 'coda';
UPDATE tools SET short_description_en = 'Prepaid cards and professional expense management.', long_description_en = 'Soldo provides prepaid Mastercard cards to control team spending. Each card has a defined budget, and expenses are automatically categorised. Accounting integration reduces reconciliation time. It''s a simpler alternative to Moss for small structures that just want to distribute budgets without complexity.' WHERE slug = 'soldo';
UPDATE tools SET short_description_en = 'Time management and HR scheduling.', long_description_en = 'Kelio (formerly Bodet Software) manages working time, scheduling, and access control. It''s a field-oriented HR tool: time clocking, team planning, hour tracking. For organisations with variable schedules or shift work, Kelio delivers significant efficiency gains over manual tracking.' WHERE slug = 'kelio';
UPDATE tools SET short_description_en = 'Legal and contractual document automation.', long_description_en = 'Captaindoc automates the creation of legal and contractual documents from templates. It generates personalised contracts, amendments, and legal documents in a few clicks. For organisations that regularly produce similar documents, it''s a considerable time saver.' WHERE slug = 'captaindoc';
UPDATE tools SET short_description_en = 'Automated expense reports with OCR.', long_description_en = 'Rydoo automates expense reports with OCR receipt recognition, multi-country tax compliance, and direct ERP integration. The mobile app lets you scan a receipt in 5 seconds. For travelling consultants, it''s a massive time saving compared to manual spreadsheets.' WHERE slug = 'rydoo';
UPDATE tools SET short_description_en = 'Cloud HCM and finance for large enterprises.', long_description_en = 'Workday is the reference cloud HR and finance platform for large enterprises. It covers HCM (human capital management), financial planning, payroll, and HR analytics. For organisations of 200+ people, it''s a structural investment. For smaller structures, it''s oversized and too expensive.' WHERE slug = 'workday';
UPDATE tools SET short_description_en = 'Simple and fast electronic signature.', long_description_en = 'SignRequest (acquired by Box) offers simple, accessible electronic signature. The tool focuses on essentials: send a document, get it signed, archive it. No frills, no unnecessary complexity. For freelancers and small teams signing a few documents per month, it''s a cheaper alternative to DocuSign.' WHERE slug = 'signrequest';
UPDATE tools SET short_description_en = 'French payroll and social management software.', long_description_en = 'Silae is the reference payroll software in France, used by thousands of accounting firms and SMEs. It handles the complexity of French labour law (collective agreements, DSN, withholding tax) with recognised reliability. For French companies, it''s often the default choice recommended by their accountant.' WHERE slug = 'silae';
UPDATE tools SET short_description_en = 'Compliance and legal monitoring solutions.', long_description_en = 'Wolters Kluwer provides legal, tax, and accounting monitoring solutions for law and finance professionals. With enriched document databases, compliance tools, and expert analyses, it''s an investment for those managing regulatory compliance daily.' WHERE slug = 'wolters-kluwer';
UPDATE tools SET short_description_en = 'CRM and client portal for creatives and photographers.', long_description_en = 'Bloom is a CRM designed for independent creatives: photographers, designers, videographers. It combines lead management, proposals, contracts, invoicing, and client galleries in a clean interface. Less feature-rich than HoneyBook but more accessible in price and easier to get started with.' WHERE slug = 'bloom-crm';
UPDATE tools SET short_description_en = 'Access to official French legal texts.', long_description_en = 'Legifrance Pro provides structured access to French legal texts: codes, laws, decrees, case law. For freelancers and business owners, it''s a free and official resource to check a legal point without going through a lawyer for every question. The tool is maintained by the French government.' WHERE slug = 'legifrance-pro';
UPDATE tools SET short_description_en = 'Electronic signatures and digital identity.', long_description_en = 'Connective specialises in electronic signature and digital identity with a focus on European compliance (eIDAS). It offers simple, advanced, and qualified signatures, making it suitable for regulated sectors. For companies dealing with public administrations or banks, it''s a compliance advantage.' WHERE slug = 'connective';
UPDATE tools SET short_description_en = 'Advanced Microsoft project management.', long_description_en = 'Microsoft Project is the historic project management tool, specialising in advanced planning with Gantt charts, resource management, and milestone tracking. It integrates natively with the Microsoft 365 ecosystem. For traditional project managers used to waterfall methodology, it''s the reference tool. For agile teams, it''s often replaced by more flexible alternatives.' WHERE slug = 'microsoft-project';
UPDATE tools SET short_description_en = 'Personalised email outreach with automated sequences.', long_description_en = 'Lemlist is a personalised email outreach platform with multi-channel sequences (email + LinkedIn). It stands out for advanced email personalisation (dynamic images, variables) and performance tracking. For consultants and agencies doing active prospecting, it''s a mature and well-thought-out tool.' WHERE slug = 'lemlist';
UPDATE tools SET short_description_en = 'Commercial proposal software for agencies.', long_description_en = 'Nusii is a commercial proposal tool designed for agencies and consultants. It stands out for its simplicity and focus on essentials: create, send, and track proposals. No superfluous features. Appreciated for its clean design and quick onboarding.' WHERE slug = 'nusii';
UPDATE tools SET short_description_en = 'All-in-one client portal for agencies and freelancers.', long_description_en = 'SuiteDash is an all-in-one client portal for agencies and freelancers: CRM, invoicing, project management, file sharing, and branded client portal — all in one platform. The main advantage is avoiding juggling 5 different tools. The trade-off is that each function is less advanced than a dedicated tool.' WHERE slug = 'suitedash';
UPDATE tools SET short_description_en = 'Multi-channel LinkedIn + Email automation.', long_description_en = 'La Growth Machine (LGM) automates prospecting on LinkedIn, Email, and Twitter simultaneously. The French tool distinguishes itself with a sequential multi-channel approach: if the prospect doesn''t reply on LinkedIn, they''re followed up by email, then Twitter. Data enrichment is built in.' WHERE slug = 'la-growth-machine';
UPDATE tools SET short_description_en = 'Data extraction and LinkedIn automation.', long_description_en = 'PhantomBuster automates data extraction and actions on LinkedIn, Instagram, Twitter, and other platforms. It''s the growth hackers'' tool: scraping LinkedIn profiles, sending automated connections, enriching prospect lists. Powerful but use with judgment to stay within platform limits.' WHERE slug = 'phantombuster';
UPDATE tools SET short_description_en = 'Automated LinkedIn prospecting.', long_description_en = 'Waalaxy automates LinkedIn prospecting with a more accessible approach than PhantomBuster. It offers action sequences (profile visit, connection, message) and a built-in CRM to track prospects. It''s the popular choice in France for LinkedIn prospecting, with a good balance between simplicity and power.' WHERE slug = 'waalaxy';
UPDATE tools SET short_description_en = 'Professional commercial proposals.', long_description_en = 'Proposify lets you create professional commercial proposals with real-time tracking. It offers customisable templates, built-in electronic signature, and analytics on client engagement (time spent per section). For consultants and agencies sending 5+ quotes per month, it''s a significant upgrade over static PDFs.' WHERE slug = 'proposify';
UPDATE tools SET short_description_en = 'Open-source automation alternative to Zapier.', long_description_en = 'Activepieces is an open-source automation platform, alternative to Zapier and Make. Self-hosted or cloud, it offers a visual workflow editor with growing integrations. For developers who want to control their automation infrastructure, it''s the sovereign choice.' WHERE slug = 'activepieces';
UPDATE tools SET short_description_en = 'Redesigned browser for productivity.', long_description_en = 'Arc reimagines the web browser around productivity: workspaces, automatically organised tabs, mini-apps, and a minimalist design. For developers and designers with 50+ open tabs, Arc imposes an organisational discipline that reduces cognitive chaos.' WHERE slug = 'arc-browser';
UPDATE tools SET short_description_en = 'Commercial proposals with tracking and signatures.', long_description_en = 'Better Proposals offers a more accessible alternative to Proposify with modern web templates. Proposals are web pages (not PDFs) enabling precise reading tracking and optimal mobile experience. The tool includes integrated signature and payment.' WHERE slug = 'better-proposals';
UPDATE tools SET short_description_en = 'Analytics for shared Notion pages.', long_description_en = 'Notionlytics adds analytics to publicly shared Notion pages. It lets you know who visits your pages, how long they stay, and which sections they read. For freelancers using Notion as a portfolio or client documentation, it''s a valuable insight.' WHERE slug = 'notionlytics';
UPDATE tools SET short_description_en = 'Creative portfolios with experimental design.', long_description_en = 'Cargo is the platform for creatives who want a portfolio that stands out. It offers experimental templates and full design control with advanced typographic and animation features. It''s the choice of the international creative community for portfolios that break the mould.' WHERE slug = 'cargo-site';
UPDATE tools SET short_description_en = 'RFP and tender response automation.', long_description_en = 'Loopio automates responses to RFPs and security questionnaires. It maintains a library of reusable answers and uses AI to suggest the best responses. For companies that regularly respond to RFPs, it''s a 50-70% time saving per response.' WHERE slug = 'loopio';
UPDATE tools SET short_description_en = 'Integrated ConvertKit performance tracking.', long_description_en = 'ConvertKit Analytics provides essential newsletter metrics: subscribers, open rate, clicks, and digital product revenue. Natively integrated, it requires no setup. Data is presented clearly with trends over time.' WHERE slug = 'convertkit-analytics';
UPDATE tools SET short_description_en = 'IDE autocomplete for the terminal.', long_description_en = 'Fig adds visual autocomplete to your existing terminal (not a replacement). It provides contextual suggestions for commands, flags, and arguments — similar to IDE IntelliSense but in the terminal. Acquired by AWS, the product''s future is tied to Amazon Q Developer.' WHERE slug = 'fig-terminal';
UPDATE tools SET short_description_en = 'Networked note-taking with bidirectional links.', long_description_en = 'Roam Research popularised networked notes with bidirectional links. Every note can reference any other, creating a personal knowledge graph. For consultants, researchers, and thinkers who connect ideas across domains, it''s a transformative tool. For those who just want to take notes, it''s overkill.' WHERE slug = 'roam-research';
UPDATE tools SET short_description_en = 'Automatic AI audio cleaning.', long_description_en = 'Cleanvoice automatically cleans audio files with AI: filler word removal (um/uh), dead silence, background noise, and mouth clicks. The tool specialises in audio post-processing and works in batch mode. For podcasters and creators who manually clean audio for hours, it''s a direct time saving.' WHERE slug = 'cleanvoice';
UPDATE tools SET short_description_en = 'Advanced metrics for Beehiiv newsletters.', long_description_en = 'Beehiiv Analytics is the analytics module built into the Beehiiv newsletter platform. It provides detailed metrics: open rates, clicks, growth, revenue, and attribution. Included in all Beehiiv plans, it''s a competitive advantage over Substack whose analytics are basic.' WHERE slug = 'beehiiv-analytics';
UPDATE tools SET short_description_en = 'Modern terminal with built-in AI for developers.', long_description_en = 'Warp is a modern developer terminal with built-in AI, IDE-like text editing, and team collaboration. It reimagines the terminal experience: each command is an editable block, history is searchable, and AI can explain or generate commands. For developers who spend 2+ hours daily in the terminal, it''s a significant upgrade.' WHERE slug = 'warp';
UPDATE tools SET short_description_en = 'No-code automation at unlimited flat price.', long_description_en = 'Pabbly Connect is a Zapier alternative with a major advantage: flat price, unlimited workflows. Where Zapier charges per task (and the bill adds up fast), Pabbly offers a fixed subscription with no workflow or task limits. The integration library is smaller but covers common use cases.' WHERE slug = 'pabbly-connect';
UPDATE tools SET short_description_en = 'High-performance code editor with collaboration.', long_description_en = 'Zed is a high-performance code editor written in Rust, built by the creators of Atom. It starts in milliseconds, handles large files without slowing down, and offers native real-time collaboration. It''s the VS Code alternative for developers who prioritise speed and lightness.' WHERE slug = 'zed';
UPDATE tools SET short_description_en = 'Sync and encrypt .env files across environments.', long_description_en = 'Dotenv Vault extends the .env file concept with encryption and synchronisation. It encrypts your .env files, syncs them across developers, and securely deploys them to production. It''s the simplest solution for small teams already using dotenv.' WHERE slug = 'dotenv-vault';
UPDATE tools SET short_description_en = 'Enterprise secret management and encryption.', long_description_en = 'HashiCorp Vault is the enterprise reference for secret management, encryption, and access control. It handles dynamic secrets, automatic key rotation, and encryption-as-a-service. For large infrastructures, it''s a security cornerstone. For small teams, it''s overly complex.' WHERE slug = 'vault';
UPDATE tools SET short_description_en = 'All-in-one CRM for creative freelancers.', long_description_en = '17hats is an all-in-one management tool for creative freelancers: CRM, quotes, contracts, invoicing, scheduling, and forms. The name comes from the idea that a freelancer wears 17 different hats. The tool consolidates administrative functions so the creative can focus on their craft.' WHERE slug = '17hats';
UPDATE tools SET short_description_en = 'Open-source secret management for dev teams.', long_description_en = 'Infisical is an open-source, modern alternative to Doppler for secret management. It offers an intuitive dashboard, CI/CD integrations, and the ability to self-host. It''s the choice for teams who want Doppler''s simplicity with open-source control.' WHERE slug = 'infisical';
UPDATE tools SET short_description_en = 'Editorial web design with advanced animations.', long_description_en = 'Readymag is a web creation tool focused on editorial design. It offers pixel-perfect control with advanced animations, flexible grids, and refined typographic rendering. It''s the choice for designers who want to create unique web experiences without coding, with results close to a custom-coded site.' WHERE slug = 'readymag';
UPDATE tools SET short_description_en = 'Studio manager for photographers and videographers.', long_description_en = 'Táve is a management tool designed specifically for professional photographers and videographers. It manages the complete pipeline: from initial enquiry to final delivery, including contracts, invoicing, and session scheduling. The built-in financial reporting gives a clear view of profitability by service type.' WHERE slug = 'tave';
