UPDATE tools SET short_description_en = 'Google''s AI that doubles its performance every 3 months.', long_description_en = 'Gemini 3.1 Pro (February 2026) is the latest evolution of Google''s AI, designed for complex tasks requiring advanced reasoning. The model doubled its reasoning performance in 3 months (ARC-AGI-2: 77.1% vs 38% for Gemini 3 Pro). Gemini excels at creative coding (animated SVG generation, 3D dashboards, interactive interfaces), complex system synthesis (APIs → user-friendly design), and logical reasoning. API pricing ($2/$12/M tokens) is competitive with Claude. For freelancers working on complex technical projects, generative design, or who want native Google Workspace integration, Gemini 3.1 Pro is a serious option. Note: the model is in preview, so less stable than ChatGPT/Claude.' WHERE slug = 'gemini';
